[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "shipment-summary",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateDataModel": {
      "surfaceId": "shipment-summary",
      "value": {
        "shipments": [
          {
            "id": "94001",
            "status": "Out for Delivery",
            "location": "Chicago, IL, USA"
          },
          {
            "id": "94002",
            "status": "In Transit",
            "location": "Memphis, TN, USA"
          },
          {
            "id": "94003",
            "status": "Label Created",
            "location": "Seattle, WA, USA"
          }
        ]
      }
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "shipment-summary",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "spacing": "medium"
          },
          "children": [
            {
              "id": "title"
            },
            {
              "id": "status_card"
            },
            {
              "id": "arrival_card"
            },
            {
              "id": "assumptions_text"
            },
            {
              "id": "actions_divider"
            },
            {
              "id": "actions_title"
            },
            {
              "id": "actions_row"
            }
          ]
        },
        {
          "id": "title",
          "type": "Text",
          "properties": {
            "text": "Summary of Your Shipments as of 2024-05-20",
            "style": "titleLarge"
          }
        },
        {
          "id": "status_card",
          "type": "Card",
          "children": [
            {
              "id": "status_column"
            }
          ]
        },
        {
          "id": "status_column",
          "type": "Column",
          "properties": {
            "spacing": "small"
          },
          "children": [
            {
              "id": "status_title"
            },
            {
              "id": "status_list"
            }
          ]
        },
        {
          "id": "status_title",
          "type": "Text",
          "properties": {
            "text": "Package Status Overview",
            "style": "titleMedium"
          }
        },
        {
          "id": "status_list",
          "type": "List",
          "properties": {
            "childrenBinding": "shipments"
          },
          "children": [
            {
              "id": "status_list_template"
            }
          ]
        },
        {
          "id": "status_list_template",
          "type": "ListItem",
          "properties": {
            "template": true,
            "primaryText": "ID: ${item.id}",
            "secondaryText": "Status: ${item.status}",
            "tertiaryText": "Location: ${item.location}"
          }
        },
        {
          "id": "arrival_card",
          "type": "Card",
          "children": [
            {
              "id": "arrival_column"
            }
          ]
        },
        {
          "id": "arrival_column",
          "type": "Column",
          "properties": {
            "spacing": "small"
          },
          "children": [
            {
              "id": "arrival_title"
            },
            {
              "id": "arrival_list"
            }
          ]
        },
        {
          "id": "arrival_title",
          "type": "Text",
          "properties": {
            "text": "Estimated Arrival Order",
            "style": "titleMedium"
          }
        },
        {
          "id": "arrival_list",
          "type": "List",
          "properties": {
            "listType": "ordered"
          },
          "children": [
            {
              "id": "arrival_item_1"
            },
            {
              "id": "arrival_item_2"
            },
            {
              "id": "arrival_item_3"
            }
          ]
        },
        {
          "id": "arrival_item_1",
          "type": "ListItem",
          "properties": {
            "primaryText": "Package ID: 94001 (Out for Delivery)",
            "secondaryText": "This package is the closest to delivery and is likely to arrive today (May 20th) or the next business day."
          }
        },
        {
          "id": "arrival_item_2",
          "type": "ListItem",
          "properties": {
            "primaryText": "Package ID: 94002 (In Transit)",
            "secondaryText": "This package has arrived at a sorting facility and is actively moving. It will likely arrive after package 94001, typically within a few business days depending on its final destination."
          }
        },
        {
          "id": "arrival_item_3",
          "type": "ListItem",
          "properties": {
            "primaryText": "Package ID: 94003 (Label Created, pending pickup)",
            "secondaryText": "This package has only had its label created and has not yet been picked up by the carrier. It will be the last to arrive, as its journey has not yet begun."
          }
        },
        {
          "id": "assumptions_text",
          "type": "Text",
          "properties": {
            "text": "Assumptions: These estimates are based on typical shipping timelines for each status. Actual delivery times may vary due to carrier operations, unforeseen delays, or specific service levels.",
            "style": "caption"
          }
        },
        {
          "id": "actions_divider",
          "type": "Divider"
        },
        {
          "id": "actions_title",
          "type": "Text",
          "properties": {
            "text": "Quick Actions",
            "style": "labelLarge"
          }
        },
        {
          "id": "actions_row",
          "type": "Row",
          "properties": {
            "mainAxisAlignment": "start",
            "spacing": "small"
          },
          "children": [
            {
              "id": "button_94001"
            },
            {
              "id": "button_94002"
            },
            {
              "id": "button_94003"
            }
          ]
        },
        {
          "id": "button_94001",
          "type": "Button",
          "properties": {
            "label": "Track Package 94001",
            "action": {
              "functionCall": {
                "call": "openUrl",
                "args": {
                  "url": "http://example.com/track/94001"
                }
              }
            }
          }
        },
        {
          "id": "button_94002",
          "type": "Button",
          "properties": {
            "label": "Track Package 94002",
            "action": {
              "functionCall": {
                "call": "openUrl",
                "args": {
                  "url": "http://example.com/track/94002"
                }
              }
            }
          }
        },
        {
          "id": "button_94003",
          "type": "Button",
          "properties": {
            "label": "Track Package 94003",
            "action": {
              "functionCall": {
                "call": "openUrl",
                "args": {
                  "url": "http://example.com/track/94003"
                }
              }
            }
          }
        }
      ]
    }
  }
]
